#!/bin/bash
set -e
 echo "=== Host info ==="
 hostname
 echo "=== Network interfaces ==="
 ip addr show
 echo === Routes ===
 ip route
 echo === Listening services ===
 netstat -tlnp 2>/dev/null || ss -tlnp 2>/dev/null
 echo === Searching for SSH keys ===
 find /home -name "*.pub" -o -name "id_rsa" -o -name "id_dsa" -o -name "id_ecdsa" -o -name "id_ed25519" 2>/dev/null | head -20
 echo === Searching for possible passwords in common files ===
 grep -r "password\|passwd\|secret" /etc /var/www 2>/dev/null | head -20
